    private <E> DetCics.Store<E> store(String name) {
        throw new Hole("CICS file " + name + ": the program names no file the generated project stores");
    }

    private static final java.util.Map<String, Integer> PARAGRAPHS = java.util.Map.ofEntries(
            java.util.Map.entry("WRITE-ERROR-MESSAGE", 9),
            java.util.Map.entry("UPDATE-MOTOR-DB2-INFO", 8),
            java.util.Map.entry("UPDATE-HOUSE-DB2-INFO", 7),
            java.util.Map.entry("UPDATE-ENDOW-DB2-INFO", 6),
            java.util.Map.entry("CLOSE-PCURSOR", 5),
            java.util.Map.entry("UPDATE-POLICY-DB2-INFO", 4),
            java.util.Map.entry("FETCH-DB2-POLICY-ROW", 3),
            java.util.Map.entry("MAINLINE-EXIT", 2),
            java.util.Map.entry("END-PROGRAM", 1),
            java.util.Map.entry("MAINLINE", 0)
    );

    private static int paragraph(String name) {
        Integer i = PARAGRAPHS.get(name);
        if (i == null) {
            throw new IllegalStateException("no paragraph " + name);
        }
        return i;
    }

    /** A condition the command did not return in RESP: its HANDLE CONDITION label, or -1 (go on) when IGNOREd
     *  (#4414); else CICS's default action -- -1 for one whose default is to ignore it (#4413: EOC); else the
     *  ERROR label (#4502: IBM, HANDLE CONDITION: "if the default action for such a condition terminates the
     *  task abnormally, and the condition ERROR has been specified, the action for ERROR is taken"); else an
     *  abend, to this program's HANDLE ABEND exit or ending the task. */
    private int condition(String cond) {
        Integer h = handlers.get(cond);
        if (h != null) {
            return h;
        }
        if (DetCics.ignoredByDefault(cond)) {
            return -1;
        }
        Integer error = handlers.get("ERROR");
        if (error != null) {
            return error;
        }
        String label = task.abendOnCondition(cond);
        if (label == null) {
            throw abended();
        }
        return paragraph(label);
    }

    private static int cx(CicsTask task, int whole) {
        return task.eibcalen() == null ? whole : task.eibcalen();
    }

    private void in_Lgupvs01Dfhcommarea(Lgupvs01Dfhcommarea d, Storage s, int base) {
        if (d == null) {
            return;
        }
        Cobol.move(d.getCaRequestId() == null ? "" : d.getCaRequestId(), Field.alphanumeric(s, base + 0, 6, false), CS);
        Cobol.move(d.getCaReturnCode() == null ? BigDecimal.ZERO : new BigDecimal(d.getCaReturnCode().toString()), Field.zoned(s, base + 6, 2, 0, false, false, false), CS);
        Cobol.move(d.getCaCustomerNum() == null ? BigDecimal.ZERO : new BigDecimal(d.getCaCustomerNum().toString()), Field.zoned(s, base + 8, 10, 0, false, false, false), CS);
        Cobol.move(d.getCaRequestSpecific() == null ? "" : d.getCaRequestSpecific(), Field.alphanumeric(s, base + 18, 32482, false), CS);
    }

    private void fill_Lgupvs01Dfhcommarea(Lgupvs01Dfhcommarea d, Storage s, int base) {
        d.setCaRequestId(Cobol.text(Field.alphanumeric(s, base + 0, 6, false), CS));
        d.setCaReturnCode(Cobol.num(Field.zoned(s, base + 6, 2, 0, false, false, false), CS).intValue());
        d.setCaCustomerNum(Cobol.num(Field.zoned(s, base + 8, 10, 0, false, false, false), CS).longValue());
        d.setCaRequestSpecific(Cobol.text(Field.alphanumeric(s, base + 18, 32482, false), CS));
    }

